// Both values are interpolated into a shell command downstream, so nothing
// but the exact shapes this pipeline signs may pass: a job uuid and a 32
// character hex digest. Anything else is rejected here, before the command
// node can see it.
const job = String($json.query?.job || '');
const sig = String($json.query?.sig || '');
const valid = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i.test(job) && /^[0-9a-f]{32}$/i.test(sig) && Boolean($env.MARK_APPLIED_SECRET);
return [{ json: { valid, job: valid ? job.toLowerCase() : '', sig: valid ? sig.toLowerCase() : '' } }];

const result = JSON.parse($json.stdout);
const role = [result.company, result.title].filter(Boolean).join(' — ');
const message = result.ok
  ? (result.alreadyApplied ? 'Already in the ledger: ' + role : 'Marked applied: ' + role)
  : ({ disabled: 'Mark-applied is not configured on this deployment.', bad_signature: 'That link is not valid.', unknown_job: 'That role is no longer in the database.', notion_failed: 'Notion refused the write: ' + (result.error || 'unknown error') }[result.reason] || 'Could not mark this role applied.');
return [{ json: { ok: result.ok, html: '<!doctype html><meta name="viewport" content="width=device-width"><title>Job discovery</title><body style="font:16px/1.5 -apple-system,system-ui,sans-serif;padding:2rem;max-width:34rem"><p>' + message.replace(/[&<>]/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])) + '</p><p style="color:#666">It will not appear in future digests.</p>' } }];
